// 42-tap direct-form FIR, 8-bit samples, unpipelined MAC cone (the long
// register-to-register path -> lower Fmax; pipeline it to go faster).
module firr42_v3 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:41];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 8'd25 + 2*8'd1 + 2*8'd2 + 2*8'd3 + 2*8'd4 + 2*8'd5 + 2*8'd6 + 2*8'd7 + 2*8'd8 + 2*8'd9 + 2*8'd10 + 2*8'd11 + 2*8'd12 + 2*8'd13 + 2*8'd14 + 2*8'd15 + 2*8'd16 + 2*8'd17 + 2*8'd18 + 2*8'd19 + 2*8'd20 + 2*8'd21 + 2*8'd22 + 2*8'd23 + 2*8'd24 + 2*8'd25 + 2*8'd26 + 2*8'd27 + 2*8'd28 + 2*8'd29 + 2*8'd30 + 2*8'd31 + 2*8'd32 + 2*8'd33 + 2*8'd34 + 2*8'd35 + 2*8'd36 + 2*8'd37 + 2*8'd38 + 2*8'd39 + 2*8'd40 + 2*8'd41 + (8'd42)*x;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 42; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 42; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule
